function topic(title,shortTitle,text,background,boundary,...refs){return {title,shortTitle,text,background,boundary,refs};}
function product(key,vendor,name,sku,format,model,readout,task,boundary,ref){return {key,vendor,name,sku,format,model,readout,task,boundary,ref};}
function method(key,title,tag,question,model,readout,decision,limit,refs,links=[]){return {key,title,tag,question,model,readout,decision,limit,refs,links};}
