function map(title,intro,root,branches,conclusion,note,refs){return {title,intro,root:{title:root[0],sub:root[1]},branches:branches.map(([title,nodes,parallel=false])=>({title,tone:parallel?'regulation':'activation',...(parallel?{relation:'topics'}:{}),nodes:nodes.map(([title,sub])=>({title,sub}))})),conclusion,note,refs};}

