 const biology=d.topics.map((b,i)=>({id:`bio-topic-${i+1}`,title:b.title,shortTitle:b.shortTitle,text:b.text,refs:b.refs.map(ref)}));
 const biologyReading={groups:[
  {id:'foundation',level:'分子层面',title:'先认识靶点与作用基础',question:d.topics.slice(0,3).map(t=>t.shortTitle).join(' · '),topics:[0,1,2]},
  {id:'function',level:'细胞与调控',title:'再看功能如何产生与调整',question:d.topics.slice(3,6).map(t=>t.shortTitle).join(' · '),topics:[3,4,5]},
  {id:'context',level:'组织与研究情境',title:'连接整体作用与干预证据',question:d.topics.slice(6,9).map(t=>t.shortTitle).join(' · '),topics:[6,7,8]}
 ],topics:d.topics.map(b=>({evidence:[['文献背景',b.background,b.refs.map(ref)],['解读边界',b.boundary]]}))};
